// A change is applied by editing one source file. Every step of that can fail for a reason a person
// can act on, so the library returns a typed refusal rather than throwing: an unmapped route, a
// source that is generated by the site's build, a file that changed since the change was drafted, a
// document the editor cannot express. Refusals carry a message written for a person and are the
// only failure shape the callers need to branch on.

/** Why a change cannot be applied (or mapped) as asked. */
export type RefusalCode =
  /** The route, file, element or rule the change names is not there. */
  | 'not_found'
  /** Several things match equally well, so picking one would be a guess. */
  | 'ambiguous'
  /** The file's current value is not the `before` the change was drafted against. */
  | 'stale'
  /** The target cannot express this change, or the editor cannot edit it safely. */
  | 'unsupported'
  /** The change itself is malformed for its operation. */
  | 'invalid'
  /** Applying it would contradict something already in the file. */
  | 'conflict';

export interface Refusal {
  ok: false;
  code: RefusalCode;
  /** A sentence a person can act on; never contains a file's whole contents. */
  reason: string;
  /** Extra facts for the change-set UI (candidate paths, the current value, a suggestion). */
  details?: Record<string, unknown>;
}

export function refuse(code: RefusalCode, reason: string, details?: Record<string, unknown>): Refusal {
  return details === undefined ? { ok: false, code, reason } : { ok: false, code, reason, details };
}

/** A result that either succeeded or refused, for code that does not throw on expected failures. */
export type Refusable<T> = T | Refusal;

export function isRefusal(value: unknown): value is Refusal {
  return typeof value === 'object' && value !== null && (value as { ok?: unknown }).ok === false;
}
